# -*- coding: utf-8 -*-
"""Spec nodes 8, 9, 10, 11 implemented EXACTLY as written in the spec,
run against /workspace for all three entry points.
"""
import sys
sys.path.insert(0, '/workspace')

from unidecode import (unidecode, unidecode_expect_ascii,
                       unidecode_expect_nonascii, UnidecodeError)

ENTRY = [
    ('unidecode', unidecode),
    ('unidecode_expect_ascii', unidecode_expect_ascii),
    ('unidecode_expect_nonascii', unidecode_expect_nonascii),
]

results = []


def check(node, entry, label, fn):
    try:
        fn()
    except AssertionError as e:
        results.append(('FAIL', node, entry, label, str(e)))
    except Exception as e:
        results.append(('ERROR', node, entry, label,
                        '%s: %s' % (type(e).__name__, e)))
    else:
        results.append(('PASS', node, entry, label, ''))


def eq(got, want, ctx=''):
    assert got == want, 'got %r want %r %s' % (got, want, ctx)


for name, u in ENTRY:
    # ---------------- Node 8: errors='ignore' ----------------
    def n8a(u=u):
        eq(u("test \U000f0000 test", errors='ignore'), 'test  test')

    def n8b(u=u):
        eq(u("Hello  World", errors='ignore'), "Hello  World")

    check(8, name, "ignore PUA-plane15", n8a)
    check(8, name, "ignore U+E000", n8b)

    # ---------------- Node 9: errors='replace' ----------------
    def n9a(u=u):
        eq(u("test \U000f0000 test", errors='replace'), 'test ? test')

    def n9b(u=u):
        eq(u("test \U000f0000 test", errors='replace', replace_str='[UNK]'),
           'test [UNK] test')

    check(9, name, "replace default '?'", n9a)
    check(9, name, "replace_str='[UNK]'", n9b)

    # ---------------- Node 10: errors='strict' ----------------
    def n10(u=u):
        try:
            u("test \U000f0000 test", errors='strict')
        except UnidecodeError as e:
            assert e.index is not None, 'UnidecodeError.index is None'
        else:
            raise AssertionError('no UnidecodeError raised')

    check(10, name, "strict raises w/ non-None index", n10)

    # ---------------- Node 11: errors='preserve' ----------------
    def n11(u=u):
        s = "test \U000f0000 test"
        eq(u(s, errors='preserve'), s)

    check(11, name, "preserve keeps original char", n11)


width = max(len(r[3]) for r in results)
for status, node, entry, label, msg in results:
    print('%-5s node%-3s %-26s %-*s %s' % (status, node, entry, width, label, msg))

bad = [r for r in results if r[0] != 'PASS']
print()
print('TOTAL %d, FAILURES %d' % (len(results), len(bad)))
sys.exit(1 if bad else 0)

